from flask import Flask, request, jsonify

app = Flask(__name__)

BASE_DIR = '/path/to/allowed/directory'
ALLOWED_EXTENSIONS = {'png', 'jpg', 'jpeg', 'gif'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/deleteImage')
def deleteImage():
    try:
        filename = request.args.get('filename')
        if not filename or not allowed_file(filename):
            return jsonify({'error': 'Invalid file name or extension'}), 400

        file_path = os.path.join(BASE_DIR, filename)

        if not file_path.startswith(BASE_DIR):
            return jsonify({'error': 'Attempt to delete outside allowed directory'}), 403

        os.remove(file_path)
        return jsonify({'message': 'File deleted successfully'}), 200

    except FileNotFoundError:
        return jsonify({'error': 'File not found'}), 404
    except Exception:
        return jsonify({'error': 'An error occurred'}), 500

import json
import urllib.request as request
from urllib.parse import urlparse

ALLOWLIST = ["https://example.com/data.json"]
MAX_RESPONSE_SIZE = 1024 * 1024  # 1 MB

def readJSON(url):
    parsed_url = urlparse(url)
    if parsed_url.scheme != 'https' or url not in ALLOWLIST:
        return {}
    try:
        with request.urlopen(url) as response:
            content_length = response.getheader('Content-Length')
            if content_length is not None and int(content_length) > MAX_RESPONSE_SIZE:
                return {}
            data = response.read()
            return json.loads(data)
    except (ValueError, json.JSONDecodeError):
        return {}
    except Exception:
        return {}

