import tarfile
import os
import logging

logging.basicConfig(level=logging.ERROR, format='%(asctime)s - %(levelname)s - %(message)s')

ALLOWED_DIR = '/tmp/'
MAX_FILE_SIZE = 10485760  # 10 MB

def extract_tar(file_name):
    try:
        with tarfile.open(file_name, 'r') as tar:
            for member in tar.getmembers():
                file_size = member.size
                if file_size > MAX_FILE_SIZE:
                    logging.error(f"File {member.name} exceeds size limit.")
                    continue

                if member.isreg():  # Check if the member is a regular file
                    safe_path = os.path.join(ALLOWED_DIR, member.name)
                    safe_path = os.path.abspath(safe_path)

                    if not safe_path.startswith(os.path.abspath(ALLOWED_DIR)):
                        logging.error(f"Attempt to extract outside allowed directory: {member.name}")
                        continue

                    tar.extract(member, path=ALLOWED_DIR)
                else:
                    logging.error(f"Ignored non-regular file: {member.name}")
    except FileNotFoundError:
        logging.error("File not found. Please check the file path.")
    except tarfile.TarError:
        logging.error("Error occurred during tar extraction.")
    except PermissionError:
        logging.error("Permission denied during extraction.")

import subprocess
import logging

allowed_commands = {"ls", "pwd", "whoami"}
disallowed_keywords = {";","&&","||","|",">","<","&","`","$","\"","'"}

logging.basicConfig(level=logging.ERROR)

def validate_command(command):
    if any(keyword in command for keyword in disallowed_keywords):
        raise ValueError("Disallowed keyword detected in command.")
    command_parts = command.split()
    if command_parts[0] not in allowed_commands:
        raise ValueError("Command not allowed.")

def executeCommand(command):
    try:
        validate_command(command)
        result = subprocess.run(command.split(), check=True, text=True, capture_output=True)
        return result.stdout
    except ValueError as ve:
        logging.error(str(ve))
        return "An error occurred while processing your command."
    except OSError as oe:
        logging.error(f"OSError: {str(oe)}")
        return "An error occurred while trying to execute the command."

