from jinja2 import Environment, FileSystemLoader, Markup, select_autoescape
import os

app = Flask(__name__)
ALLOWED_TEMPLATES = {"template.html"}
MAX_TEMPLATE_SIZE = 1024 * 10  # Max size 10 KB

@app.route('/render')
def render_response_from_env():
    template_name = request.args.get("name")

    if template_name not in ALLOWED_TEMPLATES:
        abort(400)  # User input is not in the allowlist

    env = Environment(loader=FileSystemLoader('templates'), autoescape=select_autoescape(['html', 'xml']))
    template = env.get_template(template_name)

    rendered_template = template.render()

    if len(rendered_template) > MAX_TEMPLATE_SIZE:
        abort(400)  # Template size exceeded

    return Markup(rendered_template)

